const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatRequestCountdown = expiresAt => {
  const seconds = Math.max(0, Math.ceil((Number(expiresAt) - Date.now()) / 1000));
  return Number.isFinite(seconds) && seconds > 0 ? `${String(Math.floor(seconds / 60)).padStart(2,'0')}:${String(seconds % 60).padStart(2,'0')}` : 'Checking status…';
};
function renderRiderSmsContact(s){return `<section class="cash-confirmation" style="padding:14px;margin:12px 0"><label class="eyebrow" for="rider-phone">MOBILE NUMBER FOR RIDE UPDATES</label><input class="destination-input" id="rider-phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="24" required value="${esc(s.riderPhone||'')}" placeholder="(404) 555-0123"><label style="display:flex;gap:10px;align-items:flex-start;margin-top:12px;font-size:13px;line-height:1.45"><input id="rider-sms-consent" type="checkbox" ${s.smsConsent?'checked':''} style="margin-top:3px"><span>${s.smsConfigured?'I agree to receive up to two ride texts: when the pilot accepts and when the pilot arrives at pickup. Reply STOP to opt out.':'I agree to receive up to two ride texts: when the pilot accepts and when the pilot arrives at pickup. If automatic texting is unavailable, the pilot will open Messages and tap Send. Reply STOP to opt out.'} Message and data rates may apply.</span></label></section>`}
function renderWhyTrickhopper(){return `<section class="card why-trickhopper" aria-labelledby="why-trickhopper-title"><h2 class="eyebrow" id="why-trickhopper-title">WHY TRICKHOPPER?</h2><div class="why-trickhopper-row"><span class="why-trickhopper-icon" aria-hidden="true">×</span><div><h3>Standard rideshare at night</h3><p>Late-night pickups can mean long curb waits, surge pricing, cancellations, or belongings left behind.</p></div></div><div class="why-trickhopper-row"><span class="why-trickhopper-icon bunny" aria-hidden="true">🐰</span><div><h3>The Nightlife Bunny model</h3><p>Plan your stops, reserved curbside waits, and return to your pickup in one request. Review the route and wait estimate upfront; a pilot must accept before the ride is confirmed.</p></div></div></section>`}
function pilotSmsLink(phone,state){const number=String(phone||'').replace(/[^+\d]/g,'');const id=String(state.tripId||'').slice(0,8).toUpperCase(),pin=state.boardingPin?` (Boarding PIN: ${state.boardingPin})`:'';const body=state.tripState==='COMPLETED'?`TRICKHOPPER: Your ride ${id} is complete. Thanks for riding with us!`:state.pickupArrivedAt?`TRICKHOPPER: Your pilot has arrived at pickup for ride ${id}${pin}. Open the app to see live trip status.`:`TRICKHOPPER: Your pilot accepted ride ${id}${pin} and is heading to pickup. Open the app for live trip status.`;const separator=/Android/i.test(navigator.userAgent)?'?body=':'&body=';return `sms:${number}${separator}${encodeURIComponent(body)}`}

function smsHref(phone,message){const number=String(phone||'').replace(/[^\d+]/g,'');if(number.length<7)return '';const delimiter=/iPhone|iPad|Macintosh/i.test(navigator.userAgent)?'?&body=':'?body=';return `sms:${number}${delimiter}${encodeURIComponent(message)}`}
function pilotPayoutHref(raw){
  const v=String(raw||'').trim();if(!v)return '';
  if(/^https?:\/\//i.test(v))return v;
  if(v.startsWith('$')&&/^\$[A-Za-z0-9_-]{2,30}$/.test(v))return `https://cash.app/${v}`;
  if(/^cash\.app\/\$?[A-Za-z0-9_-]+$/i.test(v))return `https://${v}`;
  if(v.startsWith('@')&&/^@[A-Za-z0-9_-]{2,30}$/.test(v))return `https://venmo.com/${v.slice(1)}`;
  return '';
}
function renderRateCard(){
  const example=calculateFare({distanceMiles:5,activeSeconds:15*60,waitSeconds:5*60});
  return `<details class="details-card"><summary>How fares & wait blocks work (Model A Split)</summary><section class="card rate-card"><div class="eyebrow">HOPATL MODEL A · WAIT LOCK + DIRECT PILOT FARE</div><h2 class="cash-title">Fare & wait block details</h2><div class="rate-grid"><span>Pilot base rate</span><strong>${money(RATE_CARD.baseFareCents)}</strong><span>Per GPS mile</span><strong>${money(RATE_CARD.perMileCents)}</strong><span>Per active trip minute</span><strong>${money(RATE_CARD.perActiveMinuteCents)}</strong><span>Wait rate</span><strong>${money(RATE_CARD.perWaitMinuteCents)}/min</strong><span>Pilot minimum</span><strong>${money(RATE_CARD.minimumFareCents)}</strong><span>Upfront Wait Lock (Stripe)</span><strong>$5.99 / $9.99 / $14.99</strong></div><p class="cash-note">Example 5 mi hop: Pilot driving & wait fare = ${money(example.totalCents)} USD (paid 100% directly to your pilot at the curb via Cash App, Zelle, Venmo, or Cash). Pre-paid Curbside Wait Lock Passkeys (<code>TH-15</code> $5.99, <code>TH-30</code> $9.99, <code>TH-60</code> $14.99) lock your reserved wait tier upfront on Stripe (<code>HOPATL</code>).</p></section></details>`;
}
function renderLegalFooter(){
  return `<details class="details-card" style="margin-top:10px"><summary>Legal, Independent Pilot Disclosure, Stripe Billing & SMS Privacy</summary><section class="card" style="margin-top:12px"><div class="eyebrow">HOPATL COMPLIANCE · PRE-ARRANGED SOFTWARE PLATFORM</div><p class="cash-note" style="margin-top:6px"><strong>Independent Pilot Disclosure & Direct Curb Settlement:</strong> TRICKHOPPER (<code>hopatl.com</code>) is a pre-arranged itinerary, shared GPS, and curbside wait-timer coordination software platform—not a common carrier or street-hail taxicab service. Rides are fulfilled by independent private pilots who collect 100% of their route & driving fare directly at the curb.</p><p class="cash-note" style="margin-top:6px"><strong>Stripe Billing & Finality (Descriptor: HOPATL):</strong> Upfront Curbside Wait Lock Passkey fees (<code>$5.99</code>, <code>$9.99</code>, <code>$14.99</code>) and All-Night Dedicated Bunny Reserves (<code>$149.00</code>) appear on statements as <strong>HOPATL</strong>. Issued <code>TH-...</code> Passkeys are non-refundable once verified in-app or once a pilot accepts and dispatches to pickup.</p><p class="cash-note" style="margin-top:6px"><strong>4-Digit Boarding PIN & SMS Privacy:</strong> Confirm your 4-Digit Bunny Boarding PIN with your pilot at the curb before boarding. Mobile numbers are used strictly for transactional ride alerts (Reply STOP to opt out) and never sold or shared. <a href="/legal" style="color:#c4b5fd;text-decoration:underline">Read full Legal & Compliance Terms →</a></p></section></details>`;
}
function shortMinutes(seconds){const minutes=Math.round(Math.max(0,Number(seconds)||0)/60);return `${minutes} min`}
function renderRouteQuote(quote,verifiedPasskey=null){
  if(!quote)return'';const route=quote.route||{},fare=quote.fare||{},hops=quote.hops||[],legs=route.legs||[],waitLockFee=quote.waitMinutes<=15?'$5.99':quote.waitMinutes<=30?'$9.99':'$14.99';
  return `<section class="card route-quote-card"><div class="eyebrow">PRE-ARRANGED ROUTE & WAIT ESTIMATE · USD</div><h2 class="cash-title">Nightlife itinerary</h2>${verifiedPasskey?`<div class="live-pill" style="margin:6px 0;display:inline-block">✓ HOP PASSKEY ACTIVE · ${esc(verifiedPasskey.passkey)} (${Number(verifiedPasskey.waitMinutes||30)} MIN RESERVED WAIT LOCKED)</div>`:''}<div class="route-itinerary"><div>📍 Live pickup</div>${hops.map((hop,index)=>`<div class="route-hop-line"><span>Hop ${index+1} · ${esc(hop.destination?.label||hop.destination?.query)}</span><strong>${Number(legs[index]?.distanceMiles||0).toFixed(1)} mi · ${shortMinutes(legs[index]?.durationSeconds)} · ${hop.waitMinutes} min wait</strong></div>`).join('')}<div class="route-hop-line"><span>↩ Return to pickup</span><strong>${Number(legs.at(-1)?.distanceMiles||0).toFixed(1)} mi · ${shortMinutes(legs.at(-1)?.durationSeconds)}</strong></div></div><div class="route-leg-grid"><span>Round-trip route</span><strong>${Number(route.totalDistanceMiles||0).toFixed(1)} mi · ${shortMinutes(route.totalDurationSeconds)}</strong></div><div class="fare-estimate"><span>Base</span><strong>${money(fare.baseCents||0)}</strong><span>Distance</span><strong>${money(fare.distanceCents||0)}</strong><span>Estimated travel time</span><strong>${money(fare.timeCents||0)}</strong>${hops.map((hop,index)=>`<span>Hop ${index+1} reserved wait · ${hop.waitMinutes} min</span><strong>${money(hop.waitMinutes*RATE_CARD.perWaitMinuteCents)}</strong>`).join('')}<span>Pilot route & driving fare (paid 100% direct to pilot at curb)</span><strong>${money(fare.totalCents||0)} USD</strong><span>Curbside Wait-Lock Passkey (upfront platform fee · HOPATL)</span><strong>${verifiedPasskey?`✓ UNLOCKED (${esc(verifiedPasskey.passkey)})`:`${waitLockFee} USD`}</strong></div><p class="cash-note">Model A Split: Your pilot keeps 100% of the ${money(fare.totalCents||0)} route fare (paid directly via Cash App, Zelle, Venmo, or Cash at the curb). A separate shared wait timer starts when the pilot records arrival at each hop; after each reserved wait plus a 2-minute grace, overrun accrues at ${money(RATE_CARD.perWaitMinuteCents)}/min.</p><p class="cash-note">Map data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a>. Google Places results are separately attributed above.</p>${quote.calculatedAt?`<p class="cash-note">Calculated ${new Date(quote.calculatedAt).toLocaleString()}</p>`:''}</section>`;
}
function fmtDuration(total){const n=Math.max(0,Math.floor(total||0));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function renderWaitSegment(s,{label,start,end,activeState,elapsedKey,billableKey,includedSeconds=0,elapsedValue,billableValue}){
  const grace=Number(s.waitGraceSeconds||120),active=s.tripState===activeState,elapsed=active&&start?Math.max(0,Math.floor((Date.now()-Date.parse(start))/1000)):Number(elapsedValue??s[elapsedKey]??0),billable=active?Math.max(0,elapsed-includedSeconds-grace):Number(billableValue??s[billableKey]??0),accrued=money(Math.round(billable/60*RATE_CARD.perWaitMinuteCents)),reservedRemaining=Math.max(0,includedSeconds-elapsed),graceRemaining=Math.max(0,includedSeconds+grace-elapsed),remaining=reservedRemaining>0?`${fmtDuration(reservedRemaining)} included wait remaining`:graceRemaining>0?`${fmtDuration(graceRemaining)} grace remaining`:`${fmtDuration(billable)} billable · ${accrued} provisional overrun`;
  const status=active?'CLOCK RUNNING':end?'CLOSED':start?'STARTED':'NOT STARTED';
  return `<div class="wait-segment"><div class="eyebrow">${label} · ${status}</div>${start?`<div class="return-wait-timer"><strong>${fmtDuration(elapsed)}</strong><span>${remaining}</span></div><p class="cash-note">Started ${new Date(start).toLocaleString()}${end?` · ended ${new Date(end).toLocaleString()}`:''}. ${includedSeconds?`${Math.floor(includedSeconds/60)}-minute reserved block, then a separate ${Math.floor(grace/60)}-minute grace period; overrun accrues at ${money(RATE_CARD.perWaitMinuteCents)} per minute, prorated by the second.`:`Separate ${Math.floor(grace/60)}-minute grace period; then ${money(RATE_CARD.perWaitMinuteCents)} per minute accrues, prorated by the second and rounded to cents.`}</p>`:`<p class="cash-note">This clock starts when the pilot records arrival. Both portals will show the timestamp and elapsed/billable duration.</p>`}</div>`;
}
function renderReturnWait(s,role){
  const hops=s.routeQuote?.hops||[],current=Math.min(Number(s.stopIndex||0),Math.max(0,hops.length-1)),waits=s.stopWaits||[];return `<section class="card return-wait-card"><div class="eyebrow">NIGHTLIFE HOPS · SHARED TRIP TIMELINE</div><h2 class="cash-title">Stop & wait record</h2>${renderWaitSegment(s,{label:'Pickup wait',start:s.pickupArrivedAt,end:s.rideStartedAt,activeState:'WAITING_PICKUP',elapsedKey:'pickupWaitElapsedSeconds',billableKey:'pickupWaitBillableSeconds'})}${hops.map((hop,index)=>{const record=waits[index]||{};return `<div class="stop-timeline ${index===current?'current-stop':''}"><strong>Hop ${index+1} · ${esc(hop.destination?.label||hop.destination?.query||'Stop')}</strong>${renderWaitSegment(s,{label:`Reserved curbside wait · ${hop.waitMinutes} min`,start:record.arrivedAt,end:record.departedAt,activeState:index===current&&['WAITING_HOP','WAITING_RETURN'].includes(s.tripState)?s.tripState:'',elapsedKey:'elapsedSeconds',billableKey:'billableSeconds',elapsedValue:record.elapsedSeconds,billableValue:record.billableSeconds,includedSeconds:Number(hop.waitMinutes||0)*60})}</div>`}).join('')}${role!=='pilot'&&['WAITING_HOP','WAITING_RETURN'].includes(s.tripState)?`<a class="btn-secondary" style="display:block;margin-top:10px;text-align:center;text-decoration:none" href="https://buy.stripe.com/test_00w5kFeAJb8F3fK46ib7y0p" target="_blank" rel="noopener noreferrer">⏱️ Party Longer · +15 Min Curbside Wait Extension ($4.99) →</a>`:''}${role==='pilot'&&s.tripState==='EN_ROUTE'?'<button class="btn-secondary" id="arrive-pickup">Arrived at pickup · start pickup wait</button>':''}${role==='pilot'&&s.tripState==='WAITING_PICKUP'?'<button class="btn-primary" id="start-outbound">Rider boarded · start route →</button>':''}${role==='pilot'&&s.tripState==='ACTIVE'?`<p class="page-subtitle">Navigate to Hop ${current+1}: ${esc(hops[current]?.destination?.label||hops[current]?.destination?.query||'selected stop')}</p><button class="btn-secondary" id="arrive-current-stop">Arrived at Hop ${current+1} · start shared wait</button>`:''}${role==='pilot'&&s.tripState==='WAITING_HOP'?`<button class="btn-primary" id="start-next-hop">Depart Hop ${current+1} · continue to next stop →</button>`:''}${role==='pilot'&&s.tripState==='WAITING_RETURN'?'<button class="btn-primary" id="start-return-leg">Depart final stop · start return to pickup →</button>':''}</section>`;
}

