function render() {
  const root = document.getElementById('app'); if (!root) return;
  const retainedLiveMap=root.querySelector('#live-map');
  const focusedAddress=document.activeElement?.matches?.('[data-destination-index]')?{id:document.activeElement.id,start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null;
  const s = store.getState(), role = s.activeMode, other = role === 'pilot' ? 'rider' : 'pilot';
  if(s.backendStatus!=='ready'){
    root.innerHTML=`<div class="app-shell">${renderHeader(s)}<div class="demo-banner" role="note"><strong>CONTROLLED TEST MODE · LIVE GPS</strong><span>Use with consenting test participants. GPS is shared between the rider and pilot portals.</span></div><main class="content-body"><section class="card"><div class="eyebrow">TRIP SERVICE STATUS</div><h1 class="cash-title">${s.backendStatus==='checking'?'Checking trip service…':'Trip service is unavailable'}</h1><p class="page-subtitle">${s.backendStatus==='checking'?'Checking whether the shared trip service is available.':'The trip service is unavailable. Connect the shared API and storage, then retry to continue testing.'}</p>${s.backendStatus==='offline'?'<button class="btn-secondary" id="retry-backend">Check connection again</button>':''}</section></main></div>`;
    document.getElementById('retry-backend')?.addEventListener('click',()=>store.checkBackend());
    return;
  }

  if(role==='pilot'&&!store.driverToken){root.innerHTML=`<div class="app-shell pilot-shell">${renderHeader(s)}<main class="content-body"><section class="card"><div class="eyebrow">PRIVATE DRIVER PORTAL</div><h1 class="cash-title">Pilot sign in</h1><p class="page-subtitle">Enter your details so dispatch can identify you and riders can pay your driving fare 100% directly at the curb. Returning pilots are saved in the dispatch database.</p><form id="driver-login-form"><label class="eyebrow" for="pilot-display-name">PILOT NAME / CALLSIGN</label><input class="destination-input" id="pilot-display-name" autocomplete="nickname" required maxlength="60" aria-label="Pilot name or callsign" value="${esc(s.driverName||'')}"><label class="eyebrow" for="pilot-phone">MOBILE NUMBER</label><input class="destination-input" id="pilot-phone" type="tel" inputmode="tel" autocomplete="tel" required maxlength="24" aria-label="Pilot mobile number" placeholder="(404) 555-0123" value="${esc(s.driverPhone||'')}"><label class="cash-note" for="pilot-sms-consent"><input id="pilot-sms-consent" type="checkbox" ${s.driverPhone?'checked':''} required> I agree that dispatch may contact me by SMS about ride requests. Texts are initiated by a person from a messaging app; carrier fees may apply. Reply STOP to opt out.</label><p class="cash-note">Dispatch operators can view this number in your pilot profile. If Messages opens, review the text and tap Send; the browser cannot send it automatically.</p><label class="eyebrow" for="pilot-vehicle">VEHICLE · MAKE, MODEL, COLOR</label><input class="destination-input" id="pilot-vehicle" autocomplete="off" maxlength="100" aria-label="Vehicle make model and color" placeholder="e.g. blue 2023 Honda Accord" value="${esc(s.driverVehicle||'')}"><label class="eyebrow" for="pilot-plate">LICENSE PLATE (OPTIONAL)</label><input class="destination-input" id="pilot-plate" autocomplete="off" maxlength="12" aria-label="Vehicle license plate" placeholder="Plate shown only after acceptance" value="${esc(s.driverPlate||'')}"><label class="eyebrow" for="pilot-payout">DIRECT PAYOUT HANDLE ($CASHTAG, ZELLE, VENMO, OR CASH)</label><input class="destination-input" id="pilot-payout" autocomplete="off" maxlength="80" aria-label="Pilot direct payout handle" placeholder="e.g. $RockoATL or Zelle (404) 555-0199" value="${esc(s.driverPayout||'')}"><label class="eyebrow" for="driver-access-code">ACCESS CODE OR TH-PL PILOT PASSKEY</label><input class="destination-input" id="driver-access-code" type="password" autocomplete="current-password" required maxlength="160" aria-label="Driver access code or TH-PL passkey" placeholder="Access code or TH-PL-XXXX-XXXX-XXXX"><button class="btn-primary booking-action" type="submit" ${s.driverLoginBusy?'disabled':''}>${s.driverLoginBusy?'Signing in…':'Sign in →'}</button></form>${s.driverLoginError?`<p class="cash-dispute" role="alert">${esc(s.driverLoginError)}</p>`:''}</section></main></div>`;document.getElementById('driver-login-form')?.addEventListener('submit',event=>{event.preventDefault();store.loginDriver(document.getElementById('driver-access-code')?.value||'',document.getElementById('pilot-display-name')?.value||'',document.getElementById('pilot-phone')?.value||'',document.getElementById('pilot-vehicle')?.value||'',document.getElementById('pilot-plate')?.value||'',document.getElementById('pilot-payout')?.value||'',document.getElementById('pilot-sms-consent')?.checked===true)});return}
  const pilot = role === 'pilot', own = s.liveLocations[role], ownActive = s.gpsActiveByRole[role];
  const stageCopy = ({IDLE:'Ready when you are',REQUESTED:'Ride request sent',EN_ROUTE:'Driver connected',WAITING_PICKUP:'Pickup wait',ACTIVE:'Ride in progress',WAITING_HOP:'Stop wait',WAITING_RETURN:'Final stop wait',RETURNING:'Return trip',COMPLETED:'Ride complete',CANCELLED:'Request cancelled',EXPIRED:'Request expired'})[s.tripState];
  let controls = '';
  let smsControls = '';
  if (s.tripState === TRIP_STATES.IDLE && !pilot && !s.bookingPickup) controls = `<section class="card nightlife-planner booking-card"><div class="booking-step-label"><span>1</span><span>Pickup</span></div><h2 class="booking-title">Where should we pick you up?</h2><p class="booking-intro">Use your phone’s current location to start your ride request.</p><div class="planner-origin"><div><span class="eyebrow">PICKUP LOCATION</span><strong>Current location</strong><small>Your location is shared only after you allow it.</small></div><span class="live-pill">${s.gpsRequestingByRole?.rider?'LOCATING…':'GPS REQUIRED'}</span></div>${renderRiderSmsContact(s)}<button class="btn-primary booking-action" id="start-request" ${s.gpsRequestingByRole?.rider?'disabled':''}>${s.gpsRequestingByRole?.rider?'Finding your location…':'Use current location'}</button>${s.gpsRequestingByRole?.rider?'<p class="gps-waiting" role="status">Waiting for a GPS fix. Your ride request has not been sent.</p>':''}${s.gpsErrors.rider?`<p class="gps-inline-error" role="alert">${esc(s.gpsErrors.rider)}</p>`:''}<p class="booking-footnote">Your browser will ask for location access. No pickup pin is guessed or saved.</p></section>`;
  if (s.tripState === TRIP_STATES.IDLE && !pilot && s.bookingPickup) controls = `<section class="card destination-card nightlife-planner booking-card"><div class="booking-step-label"><span>2</span><span>Destination</span></div><h2 class="booking-title">Where are you going?</h2><p class="booking-intro">Your pickup is confirmed. Search and select the exact place.</p><div class="planner-origin compact-origin"><div><span class="eyebrow">PICKUP · CURRENT LOCATION</span><strong>Location ready</strong><small>GPS accuracy ±${Math.round(s.bookingPickup.accuracy)} m</small></div><span class="live-pill">READY</span></div>${renderRiderSmsContact(s)}<div class="hop-list">${(s.stops||[]).map((stop,index)=>`<article class="hop-card"><div class="hop-heading"><strong>${index===0?'Destination':`Stop ${index+1}`}</strong>${s.stops.length>1?`<button type="button" class="remove-hop" data-remove-hop="${index}" aria-label="Remove stop ${index+1}">Remove</button>`:''}</div><label class="eyebrow" for="destination-input-${index}">DESTINATION</label><input class="destination-input" id="destination-input-${index}" data-destination-index="${index}" maxlength="180" value="${esc(stop.destination)}" placeholder="Type a street address or place name" autocomplete="off" aria-autocomplete="list" aria-expanded="${Boolean(stop.suggestions?.length)}" aria-controls="address-suggestions-${index}"><div class="address-search-hint" role="status">${stop.suggesting?'Searching nearby places…':stop.selectedAddress?'Address confirmed.':stop.suggestionUnavailable?'Use the full-address search below.':'Type a few letters, then choose the matching address below.'}</div>${stop.selectedAddress?`<div class="selected-address"><strong>Selected destination</strong><span>${esc(stop.selectedAddress.label)}</span></div>`:''}${stop.suggestions?.length?`<div class="address-results" id="address-suggestions-${index}" role="listbox" aria-label="Address suggestions for stop ${index+1}">${stop.suggestions.map((result,resultIndex)=>`<button type="button" class="address-result" role="option" aria-selected="false" data-mapbox-suggestion="${index}" data-result-index="${resultIndex}"><strong>${esc(result.label)}</strong><small>${esc(result.name||'Address or place')}</small></button>`).join('')}<div class="address-attribution">${stop.suggestAttribution==='Google Maps'?'<span translate="no">Google Maps</span>': '© OpenStreetMap contributors via Photon'}</div></div>`:''}${stop.selectingSuggestion?'<p class="address-search-hint" role="status">Confirming selected place…</p>':''}${stop.suggestError?`<p class="cash-dispute" role="alert">${esc(stop.suggestError)}</p>`:''}${stop.suggestError&&!stop.suggesting?`<button type="button" class="btn-secondary address-search-button" data-address-search="${index}" ${stop.addressSearching?'disabled':''}>${stop.addressSearching?'Searching…':'Search full address instead'}</button>`:''}${stop.addressError?`<p class="cash-dispute" role="alert">${esc(stop.addressError)}</p>`:''}${stop.addressResults?.length?`<div class="address-results" role="listbox" aria-label="Matching places for stop ${index+1}">${stop.addressResults.map((result,resultIndex)=>`<button type="button" class="address-result" role="option" data-address-result="${index}" data-result-index="${resultIndex}"><strong>${esc(result.label)}</strong><small>${Number(result.lat).toFixed(5)}, ${Number(result.lng).toFixed(5)}</small></button>`).join('')}</div><div class="address-attribution">© OpenStreetMap contributors</div>`:''}<div class="wait-choice"><div class="wait-choice-title">How long should the pilot wait?</div><div class="wait-choice-buttons">${[15,30,60].map(minutes=>`<button class="btn-secondary wait-choice-button ${Number(stop.waitMinutes)===minutes?'selected':''}" data-stop-index="${index}" data-wait-minutes="${minutes}" aria-pressed="${Number(stop.waitMinutes)===minutes}">${minutes} min <strong>${money(minutes*RATE_CARD.perWaitMinuteCents)}</strong></button>`).join('')}</div><small class="booking-footnote">${money(RATE_CARD.perWaitMinuteCents)} per minute · included in estimate · USD</small></div>${index===0?`<div class="spot-picks"><span class="eyebrow">POPULAR ATLANTA DESTINATIONS</span><div class="spot-pick-list">${['Ponce City Market, Atlanta, GA','Magic City, Atlanta, GA','The Battery Atlanta, Atlanta, GA','Krog Street Market, Atlanta, GA'].map(place=>`<button type="button" class="spot-pick" data-place="${esc(place)}">${esc(place.split(',')[0])}</button>`).join('')}</div></div>`:''}</article>`).join('')}</div>${s.stops.length<3?'<button class="add-hop" id="add-hop">+ Add another stop</button>':''}<div class="planner-return"><strong>Return included</strong><span>Your ride returns to the pickup location after the final stop.</span></div><label class="eyebrow" for="passenger-count">PASSENGERS</label><select id="passenger-count" class="destination-input">${[1,2,3,4].map(n=>`<option value="${n}" ${Number(s.passengerCount||1)===n?'selected':''}>${n} ${n===1?'passenger':'passengers'}</option>`).join('')}</select>${s.routeError?`<p class="cash-dispute" role="alert">${esc(s.routeError)}</p>`:''}<button class="btn-secondary" id="build-route" ${s.routeLoading?'disabled':''}>${s.routeLoading?'Calculating route…':'Get fare estimate'}</button>${s.routeQuote?`${renderRouteQuote(s.routeQuote,s.verifiedPasskey)}<button class="btn-primary booking-action" id="request-estimated-trip" ${s.requestSubmitting||!s.riderAvailability?.ready?'disabled':''}>${s.requestSubmitting?'Sending request…':`Request ride · ${money(s.routeQuote.fare?.totalCents||0)} USD`}</button><p class="booking-footnote">${s.riderAvailability?.ready?'Your request goes to the pilot queue. No pilot is assigned until a pilot accepts.':'Ride requests are available when a pilot is online and the ride lane is open.'}</p>`:''}</section>`;
  if (pilot && s.tripState === TRIP_STATES.IDLE) controls = `<section class="card"><div class="eyebrow">DRIVER AVAILABILITY</div><h2 class="cash-title">${s.driverAvailable?'You’re online':'You’re offline'}</h2><p class="page-subtitle">${s.driverAvailable?'Your portal is checking for the next request.':'Go online when you’re ready to receive a controlled test request.'}${s.driverPayout?` · Direct Curb Payout: <strong>${esc(s.driverPayout)}</strong>`:''}</p><button class="btn-${s.driverAvailable?'secondary':'primary'}" id="driver-availability">${s.driverAvailable?'Go offline':'Go online'}</button>${s.driverLoginError?`<p class="cash-dispute" role="alert">${esc(s.driverLoginError)}</p>`:''}<div style="margin-top:12px;padding:12px;border-radius:12px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.1)"><div class="eyebrow">OPTIONAL VIP PILOT PRIORITY · $29/MO</div><p class="cash-note" style="margin:4px 0 8px">Standard pilot access is 100% free (you keep 100% of direct curb fares). Upgrade to <strong>VIP Priority Pilot ($29/mo)</strong> for first dispatch priority on $149 All-Night Bunny Reserves ($100 pilot payout) + Verified Gold Chauffeur Badge.</p><a class="btn-secondary" style="display:block;text-align:center;text-decoration:none;font-size:13px" href="https://buy.stripe.com/test_4gM8wRfEN3GdaIc7iub7y0r" target="_blank" rel="noopener noreferrer">⭐ Upgrade to VIP Priority Pilot ($29/mo) →</a></div><button class="btn-secondary" id="driver-logout" style="margin-top:10px">Sign out</button></section>`;
  if ([TRIP_STATES.CANCELLED,TRIP_STATES.EXPIRED].includes(s.tripState)) controls = `<section class="card ${s.tripState==='EXPIRED'?'request-expired-card':''}" role="alert"><div class="eyebrow">${s.tripState==='EXPIRED'?'NOT BOOKED · NO PILOT ACCEPTED':'REQUEST CANCELLED'}</div><h2 class="request-expired-title">${s.tripState==='EXPIRED'?'No pilot accepted this request':'This request was cancelled'}</h2><p class="page-subtitle">${esc(s.notificationMessage||'This request is closed. No pilot was dispatched.')}</p><button class="btn-primary" id="reset-trip">${pilot?'Clear closed trip':'Try another request'}</button></section>`;
  if (pilot && s.tripState === TRIP_STATES.REQUESTED && !store.token) controls = `<section class="card"><div class="eyebrow">NEW RIDE REQUEST</div>${s.destination?`<p class="page-subtitle">Destination: ${esc(s.destination.label)}</p>`:''}<p class="page-subtitle">Party size: ${Number(s.passengerCount||1)} · request detail only. Confirm vehicle capacity before accepting.</p><p class="page-subtitle">Accepting requires a fresh GPS fix. Tap below and allow location access; the ride will connect only after GPS is received. ${s.smsConfigured?'TRICKHOPPER will send a confirmation text.':'After accepting, open Messages on this device to send the rider a confirmation. No text is sent automatically.'}</p>${s.gpsActiveByRole?.pilot?'<p class="live-pill" role="status">PILOT GPS READY</p>':''}${s.gpsErrors?.pilot?`<p class="gps-inline-error" role="alert">${esc(s.gpsErrors.pilot)} Then tap the button to retry acceptance.</p>`:''}<button class="btn-primary" id="accept-request" ${s.gpsRequestingByRole?.pilot?'disabled':''}>${s.gpsRequestingByRole?.pilot?'Getting pilot GPS…':s.gpsErrors?.pilot?'Retry GPS & accept':'Accept request · share live GPS →'}</button>${s.driverLoginError?`<p class="cash-dispute" role="alert">${esc(s.driverLoginError)}</p>`:''}</section>`;
  const activeTripStates=[TRIP_STATES.EN_ROUTE,TRIP_STATES.WAITING_PICKUP,TRIP_STATES.ACTIVE,TRIP_STATES.WAITING_HOP,TRIP_STATES.WAITING_RETURN,TRIP_STATES.RETURNING];
  const arrivalTextPending=Boolean(s.pickupArrivedAt&&s.pickupArrivalSms?.status!=='PILOT_CONFIRMED_SENT'&&s.pickupArrivalSms?.status!=='ACCEPTED_BY_PROVIDER');
  const acceptanceTextPending=s.smsConfirmation?.status==='PILOT_SMS_READY';
  const completionTextPending=s.completionSms?.status==='PILOT_SMS_READY';
  const smsFallbackNeeded=s.pickupArrivedAt?arrivalTextPending:acceptanceTextPending;
  if(pilot&&activeTripStates.includes(s.tripState)&&s.smsRecipientPhone&&(!s.smsConfigured||s.pickupArrivalSms?.status==='FAILED'||!smsFallbackNeeded))smsControls=`<section class="card sms-action-card"><div class="eyebrow">RIDER TEXT · PILOT DEVICE</div><h2 class="cash-title">${s.pickupArrivedAt?'Tell the rider you’ve arrived':'Send the rider an update'}</h2><p class="page-subtitle">${s.pickupArrivedAt?'Open the prefilled pickup-arrival text in Messages, review it, then tap Send.':'Open the prefilled acceptance text in Messages, review it, then tap Send.'} Carrier delivery is not verified here.</p><a class="btn-primary" style="display:block;text-align:center;text-decoration:none" href="${esc(pilotSmsLink(s.smsRecipientPhone,s))}">${s.pickupArrivedAt?'Open Messages · arrival alert →':'Open Messages · acceptance text →'}</a>${arrivalTextPending?'<button class="btn-secondary" id="pilot-text-sent" data-sms-milestone="pickup_arrival" style="margin-top:10px">I sent the arrival text</button>':!s.pickupArrivedAt&&acceptanceTextPending?'<button class="btn-secondary" id="pilot-text-sent" data-sms-milestone="acceptance" style="margin-top:10px">I sent the acceptance text</button>':''}${s.pickupArrivalSms?.status==='PILOT_CONFIRMED_SENT'?'<p class="live-pill" style="margin-top:10px">PILOT MARKED ARRIVAL TEXT SENT · DELIVERY UNVERIFIED</p>':''}${s.driverLoginError?`<p class="cash-dispute" role="alert">${esc(s.driverLoginError)}</p>`:''}</section>`;
  if (pilot && s.tripState === TRIP_STATES.WAITING_PICKUP) controls = `<p class="page-subtitle">The pickup wait is visible to both people. Tap when the rider boards to stop that clock and start the trip.</p>`;
  if (s.tripState === TRIP_STATES.ACTIVE && pilot) controls = `<p class="page-subtitle">Record each stop arrival in order. The next hop becomes available after its shared reserved wait is closed.</p>`;
  if (s.tripState === TRIP_STATES.WAITING_HOP && pilot) controls = `<p class="page-subtitle">The current stop timer is shared. Depart when the rider is ready to continue to the next hop.</p>`;
  if (s.tripState === TRIP_STATES.WAITING_RETURN && pilot) controls = `<p class="page-subtitle">The return-stop wait is visible to both people. Start the return leg when the rider is ready.</p>`;
  if (s.tripState === TRIP_STATES.RETURNING && pilot) controls = `<button class="btn-primary" id="complete-ride" ${!ownActive || !own || (s.fixCounts.pilot||0)<2 ? 'disabled' : ''}>Complete return trip with GPS record →</button>`;
  if (s.tripState === TRIP_STATES.COMPLETED) controls = `${pilot&&s.smsRecipientPhone?`<section class="card sms-action-card"><div class="eyebrow">RIDER TEXT · PILOT DEVICE</div><h2 class="cash-title">Confirm the trip is complete</h2><p class="page-subtitle">Open the prefilled completion text in Messages and tap Send. TRICKHOPPER records your confirmation, not carrier delivery.</p><a class="btn-primary" style="display:block;text-align:center;text-decoration:none" href="${esc(pilotSmsLink(s.smsRecipientPhone,s))}">Open Messages · trip complete →</a>${completionTextPending?'<button class="btn-secondary" id="pilot-text-sent" data-sms-milestone="completion" style="margin-top:10px">I sent the completion text</button>':s.completionSms?.status==='PILOT_CONFIRMED_SENT'?'<p class="live-pill" style="margin-top:10px">PILOT MARKED COMPLETION TEXT SENT · DELIVERY UNVERIFIED</p>':''}</section>`:''}<button class="btn-secondary" id="reset-trip">Clear trip and start over</button>`;
  controls += smsControls;
  if (activeTripStates.includes(s.tripState)) controls += `<button class="btn-secondary" id="cancel-request" style="margin-top:10px">${pilot?'End ride':'Cancel ride'}</button>`;
  const otherLocation = s.liveLocations[other];
  root.innerHTML = `<div class="app-shell ${pilot?'pilot-shell':'rider-shell'}">${renderHeader(s)}<div class="demo-banner" role="note"><strong>ATLANTA NIGHTLIFE VIP · PRE-ARRANGED WAIT &amp; RETURN</strong><span>Live GPS, 4-Digit Boarding PIN, and shared curbside wait timers.</span></div><main class="content-body">
    ${!pilot&&s.tripState===TRIP_STATES.IDLE?`<section class="card rider-hero"><div class="eyebrow">ATLANTA NIGHTLIFE · ROUNDTRIP RIDES</div><h1>Hop All Night.<br><span>Never Lose Your Ride.</span></h1><p>Our pilots can wait curbside while you pre-game, visit a lounge, grab a bite, or change fits. Plan stops, reserved waits, and a return to your pickup in one request.</p></section>`:''}
    <section class="card trip-stage-card" style="padding:20px">${!pilot&&s.tripState===TRIP_STATES.IDLE?`<div class="rider-availability ${s.riderAvailability?.ready?'ready':s.riderAvailability?.status==='UNKNOWN'?'unknown':'unavailable'}" role="status" aria-live="polite"><span class="availability-dot"></span><strong>${s.riderAvailability?.ready?'READY':s.riderAvailability?.status==='UNKNOWN'?'CHECKING AVAILABILITY':'NO PILOT AVAILABLE'}</strong><span>${esc(s.riderAvailability?.message||'Checking whether a pilot is available…')}</span></div>`:''}<div class="eyebrow">TRIP STATUS · LIVE STATUS</div><h1 class="page-title" style="margin:8px 0">${stageCopy}</h1><p class="page-subtitle">${s.notificationMessage ? esc(s.notificationMessage) : pilot ? (s.tripState===TRIP_STATES.IDLE?'Your pilot portal is ready. New requests appear here.':s.tripState==='REQUESTED'?'Review and accept the request to share live location.':'New ride requests appear here. Accepting connects the trip.') : s.tripState===TRIP_STATES.IDLE?'Enter your destination to see the fare before you request a ride.':'Ride updates and location sharing appear here as the trip progresses.'}</p>${s.boardingPin&&activeTripStates.includes(s.tripState)?`<div class="live-pill" style="margin:8px 0;display:inline-block;font-size:13px;letter-spacing:0.08em">🔐 BUNNY BOARDING PIN · <strong>${esc(s.boardingPin)}</strong> (${pilot?'Confirm with rider at curb':'Verify with pilot before boarding'})</div>`:''}${!pilot&&s.acceptedPilotName?`<div class="arrival-alert" role="status"><strong>Pilot accepted · ${esc(s.acceptedPilotName)}</strong><span>${s.acceptedPilotVehicle?esc(s.acceptedPilotVehicle):'Vehicle details have not been provided.'}${s.acceptedPilotPlate?` · Plate ${esc(s.acceptedPilotPlate)}`:''}${s.acceptedPilotPayout?` · Direct Curb Payout: ${esc(s.acceptedPilotPayout)}`:''}</span>${s.acceptedPilotPayout&&pilotPayoutHref(s.acceptedPilotPayout)?`<a class="btn-primary" style="display:block;margin-top:8px;text-align:center;text-decoration:none" href="${esc(pilotPayoutHref(s.acceptedPilotPayout))}" target="_blank" rel="noopener noreferrer">💸 Pay Pilot Direct (${esc(s.acceptedPilotPayout)}) →</a>`:''}${s.acceptedPilotPhone?`<a class="btn-secondary" style="display:block;margin-top:8px;text-align:center;text-decoration:none" href="${esc(smsHref(s.acceptedPilotPhone,`TRICKHOPPER ride ${String(s.tripId||'').slice(0,8).toUpperCase()}${s.boardingPin?` (PIN ${s.boardingPin})`:''}: `))}">Open Messages · text pilot →</a>`:''}</div>`:''}${!pilot&&s.pickupArrivedAt?`<div class="arrival-alert" role="status"><strong>Your pilot has arrived at pickup</strong><span>${new Date(s.pickupArrivedAt).toLocaleTimeString()} · ${s.pickupArrivalSms?.status==='ACCEPTED_BY_PROVIDER'?'A text was queued; carrier delivery is unverified.':s.pickupArrivalSms?.status==='PILOT_CONFIRMED_SENT'?'The pilot marked the text sent; delivery is unverified.':'Arrival is confirmed in the app. The pilot can send a text from Messages.'}</span></div>`:''}${s.smsConfirmation?.status==='ACCEPTED_BY_PROVIDER'?'<div class="live-pill">RIDER SMS QUEUED · DELIVERY STATUS MAY UPDATE</div>':s.smsConfirmation?.status==='PILOT_SMS_READY'?'<div class="live-pill">PILOT CAN SEND CONFIRMATION FROM THEIR PHONE</div>':s.smsConfirmation?.status==='PILOT_CONFIRMED_SENT'?'<div class="live-pill">PILOT MARKED TEXT SENT · CARRIER DELIVERY UNVERIFIED</div>':''}${s.tripState===TRIP_STATES.COMPLETED&&s.completionSms?.status==='PILOT_SMS_READY'?'<div class="live-pill" role="status">TRIP COMPLETE · PILOT CAN SEND A TEXT UPDATE</div>':s.completionSms?.status==='PILOT_CONFIRMED_SENT'?'<div class="live-pill" role="status">PILOT MARKED COMPLETION TEXT SENT · DELIVERY UNVERIFIED</div>':''}</section>
    <div class="primary-flow">${controls}</div>
    ${!pilot&&s.tripState===TRIP_STATES.IDLE?renderHopPassAndConcierge(s):''}
    ${!pilot&&s.tripState===TRIP_STATES.IDLE?renderWhyTrickhopper():''}
    ${(s.tripState!==TRIP_STATES.IDLE||pilot)?`<details class="details-card gps-details"><summary>${ownActive?'Live location sharing':'Location details'}</summary><section class="card" style="margin-top:12px"><div style="display:flex;align-items:center;justify-content:space-between;gap:12px"><div><strong>Your live GPS</strong><div style="font-size:12px;color:var(--text-secondary);margin-top:4px">${ownActive && own ? 'Sharing live device location' : `Location is requested when you ${pilot?'accept the request':'request pickup'}.`}</div></div>${ownActive?'<button id="gps-toggle" class="btn-secondary">Stop sharing</button>':''}</div>${s.gpsErrors[role]?`<p role="alert" style="color:#fca5a5">${esc(s.gpsErrors[role])}</p>`:''}${own?`<div class="gps-line">${Number(own.lat).toFixed(6)}, ${Number(own.lng).toFixed(6)} · ±${Math.round(own.accuracy)} m · ${new Date(own.timestamp).toLocaleTimeString()}</div>`:''}</section></details>`:''}
    ${!pilot&&s.tripState===TRIP_STATES.REQUESTED?`<section class="card request-status-card" role="status" aria-live="polite"><div class="eyebrow">REQUEST SENT · NOT BOOKED YET</div><strong>Waiting for a pilot to accept</strong><div class="request-countdown"><span>Request expires in</span><b id="request-countdown">${formatRequestCountdown(s.requestExpiresAt)}</b></div><p class="page-subtitle">Your ride is only confirmed after a pilot accepts. If no one accepts before the timer ends, this request closes and you can try again.</p><button class="btn-secondary" id="cancel-request">Cancel request</button></section>`:''}${!['IDLE','CANCELLED','EXPIRED'].includes(s.tripState)?renderLiveMap(s):''}
    ${!['IDLE','CANCELLED','EXPIRED'].includes(s.tripState)&&s.routeQuote?renderRouteQuote(s.routeQuote,s.verifiedPasskey):''}
    ${!['IDLE','CANCELLED','EXPIRED'].includes(s.tripState)?`<details class="details-card"><summary>Trip details and GPS record</summary><section class="card" style="margin-top:12px"><div class="eyebrow">OTHER DEVICE LOCATION</div><strong style="display:block;margin-top:6px">${otherLocation ? (s.gpsActiveByRole[other]?'Live location received':'Last GPS fix received') : 'Waiting for GPS fix'}</strong>${otherLocation?`<div class="gps-line">${Number(otherLocation.lat).toFixed(6)}, ${Number(otherLocation.lng).toFixed(6)} · ±${Math.round(otherLocation.accuracy)} m · ${new Date(otherLocation.timestamp).toLocaleTimeString()}</div>`:`<p class="page-subtitle">The other person must open their portal and allow location access.</p>`}<div class="eyebrow" style="margin-top:16px">TRIP TELEMETRY</div><div class="telemetry-stats"><div><b>${s.fixCounts.rider||0}</b><small>Customer GPS fixes</small></div><div><b>${s.fixCounts.pilot||0}</b><small>Driver GPS fixes</small></div><div><b>${Number(s.tripDistanceMiles||0).toFixed(2)} mi</b><small>Recorded driver track</small></div></div><p class="page-subtitle" style="margin-bottom:0">Live browser GPS and trip events are recorded by the connected service. Route estimates use OpenStreetMap services; they are not traffic-aware.</p>${s.pickupArrivedAt?`<div class="gps-line">Pickup arrival recorded ${new Date(s.pickupArrivedAt).toLocaleString()}</div>`:''}${s.rideStartedAt?`<div class="gps-line">Ride start recorded ${new Date(s.rideStartedAt).toLocaleString()}</div>`:''}${s.destinationArrivedAt?`<div class="gps-line">Drop-off arrival recorded ${new Date(s.destinationArrivedAt).toLocaleString()}</div>`:''}${s.returnStartedAt?`<div class="gps-line">Return leg started ${new Date(s.returnStartedAt).toLocaleString()}</div>`:''}${s.rideCompletedAt?`<div class="gps-line">Completed ${new Date(s.rideCompletedAt).toLocaleString()}</div>`:''}</section></details>`:''}
    ${!['IDLE','REQUESTED','CANCELLED','EXPIRED'].includes(s.tripState)?renderReturnWait(s,role):''}
    ${renderRateCard()}
    ${renderLegalFooter()}
    </main></div>`;
  const nextLiveMap=root.querySelector('#live-map');if(retainedLiveMap&&nextLiveMap)nextLiveMap.replaceWith(retainedLiveMap);updateLiveMap(s);
  document.getElementById('gps-toggle')?.addEventListener('click',()=> ownActive ? telemetry.stopLiveGPS(role) : telemetry.startLiveGPS(role));
  document.getElementById('passkey-input')?.addEventListener('input',event=>{store.state.passkeyInput=event.target.value});
  document.getElementById('verify-passkey-btn')?.addEventListener('click',()=>store.verifyPasskey(document.getElementById('passkey-input')?.value||''));
  document.getElementById('toggle-mint-drawer')?.addEventListener('click',()=>{store.state.showMintDrawer=!store.state.showMintDrawer;store.notify()});
  document.getElementById('mint-pin-input')?.addEventListener('input',event=>{store.state.mintPin=event.target.value});
  document.getElementById('mint-tier-select')?.addEventListener('change',event=>{store.state.mintTier=event.target.value});
  document.getElementById('mint-passkey-btn')?.addEventListener('click',()=>store.mintPasskey(document.getElementById('mint-pin-input')?.value||store.state.mintPin,document.getElementById('mint-tier-select')?.value||store.state.mintTier));
  document.getElementById('concierge-input')?.addEventListener('input',event=>{store.state.conciergeQuery=event.target.value});
  document.getElementById('ask-concierge-btn')?.addEventListener('click',()=>store.askConcierge(document.getElementById('concierge-input')?.value||store.state.conciergeQuery));
  document.getElementById('rider-phone')?.addEventListener('input',event=>{store.state.riderPhone=event.target.value;store.state.routeError=null});
  document.getElementById('rider-sms-consent')?.addEventListener('change',event=>{store.state.smsConsent=event.target.checked;store.state.routeError=null});
  document.getElementById('pilot-text-sent')?.addEventListener('click',event=>store.confirmPilotSmsSent(event.currentTarget.dataset.smsMilestone||'acceptance'));
  document.getElementById('start-request')?.addEventListener('click',()=>{const gps=store.pendingFixes.rider;if(store.getState().gpsActiveByRole.rider&&gps&&Date.now()-Date.parse(gps.timestamp)<30000)store.capturePickup(gps);else telemetry.startLiveGPS('rider',fix=>store.capturePickup(fix))});
  document.getElementById('build-route')?.addEventListener('click',()=>{document.querySelectorAll('[data-destination-index]').forEach(input=>store.state.stops[Number(input.dataset.destinationIndex)].destination=input.value);store.quoteDestination()});
  document.querySelectorAll('[data-place]').forEach(button=>button.addEventListener('click',()=>store.setDestinationText(button.dataset.place,0)));
  document.getElementById('passenger-count')?.addEventListener('change',event=>{store.state.passengerCount=Number(event.target.value);store.routeQuote=null;store.notify()});
  document.querySelectorAll('[data-wait-minutes]').forEach(button=>button.addEventListener('click',()=>store.setStopWait(button.dataset.waitMinutes,button.dataset.stopIndex)));
  document.querySelectorAll('[data-destination-index]').forEach(input=>{input.addEventListener('input',event=>{const index=Number(event.target.dataset.destinationIndex),stop=store.state.stops[index],query=event.target.value.trim();if(stop){const changed=stop.destination!==event.target.value;stop.destination=event.target.value;if(changed)stop.suggestionUnavailable=false;stop.addressId=null;stop.selectedAddress=null;stop.addressResults=[];stop.addressError=null;stop.suggestions=[];stop.suggesting=false;stop.suggestRequest++;clearTimeout(stop.suggestTimer);if(!stop.suggestionUnavailable){stop.suggestError=null;if(query.length>=3)stop.suggestTimer=setTimeout(()=>store.suggestAddresses(index,query),300)}}store.state.routeQuote=null;const card=event.target.closest('.hop-card');card?.querySelector('.selected-address')?.remove();card?.querySelectorAll('.address-results,.address-attribution,.cash-dispute').forEach(item=>item.remove())});input.addEventListener('keydown',event=>{const options=[...event.target.closest('.hop-card').querySelectorAll('[data-mapbox-suggestion]')],current=options.indexOf(document.activeElement);if(event.key==='ArrowDown'&&options.length){event.preventDefault();options[Math.min(current+1,options.length-1)].focus()}else if(event.key==='ArrowUp'&&options.length){event.preventDefault();if(current<=0)event.target.focus();else options[current-1].focus()}else if(event.key==='Escape'){options.forEach(option=>option.blur());event.target.focus()}})});
  document.querySelectorAll('[data-mapbox-suggestion]').forEach(button=>button.addEventListener('click',()=>{const stopIndex=Number(button.dataset.mapboxSuggestion),result=store.state.stops[stopIndex]?.suggestions?.[Number(button.dataset.resultIndex)];store.selectSuggestedAddress(stopIndex,result)}));
  document.querySelectorAll('[data-address-search]').forEach(button=>button.addEventListener('click',()=>store.searchAddresses(Number(button.dataset.addressSearch))));
  document.querySelectorAll('[data-address-result]').forEach(button=>button.addEventListener('click',()=>{const stopIndex=Number(button.dataset.addressResult),result=store.state.stops[stopIndex]?.addressResults?.[Number(button.dataset.resultIndex)];store.selectAddress(stopIndex,result)}));
  document.getElementById('add-hop')?.addEventListener('click',()=>store.addStop());
  document.querySelectorAll('[data-remove-hop]').forEach(button=>button.addEventListener('click',()=>store.removeStop(Number(button.dataset.removeHop))));
  document.getElementById('request-estimated-trip')?.addEventListener('click',()=>{const inputs=[...document.querySelectorAll('[data-destination-index]')],quote=store.getState().routeQuote;if(inputs.some((input,index)=>input.value.trim()!==quote?.hops?.[index]?.destination?.query)){store.state.routeError='A destination changed. Recalculate the estimate before requesting.';store.state.routeQuote=null;store.notify();return}store.requestRide()});
  document.getElementById('cancel-request')?.addEventListener('click',()=>store.cancelRequest());
  document.getElementById('accept-request')?.addEventListener('click',()=>telemetry.startLiveGPS('pilot',fix=>store.claimOpenRequest(fix)));
  document.getElementById('driver-availability')?.addEventListener('click',()=>store.setDriverAvailability(!store.getState().driverAvailable));
  document.getElementById('driver-logout')?.addEventListener('click',()=>store.logoutDriver());
  document.getElementById('complete-ride')?.addEventListener('click',()=>store.completeRide());
  document.getElementById('arrive-pickup')?.addEventListener('click',()=>store.waitEvent('arrive_pickup'));
  document.getElementById('start-outbound')?.addEventListener('click',()=>store.waitEvent('start_outbound'));
  document.getElementById('arrive-return-stop')?.addEventListener('click',()=>store.waitEvent('arrive_dropoff'));
  document.getElementById('arrive-current-stop')?.addEventListener('click',()=>store.waitEvent('arrive_stop'));
  document.getElementById('start-next-hop')?.addEventListener('click',()=>store.waitEvent('start_next_hop'));
  document.getElementById('start-return-leg')?.addEventListener('click',()=>store.waitEvent('start_return'));
  document.getElementById('reset-trip')?.addEventListener('click',()=>store.resetTrip());
  document.getElementById('btnToggleWakeLock')?.addEventListener('click',()=>telemetry.requestWakeLock());
  if(focusedAddress){const input=document.getElementById(focusedAddress.id);if(input){input.focus({preventScroll:true});try{input.setSelectionRange(focusedAddress.start,focusedAddress.end)}catch{}}}
}
let returnWaitTicker=null,requestWaitTicker=null;
store.subscribe(state=>{render();if(state.tripState===TRIP_STATES.COMPLETED)telemetry.stopLiveGPS(state.activeMode);if([TRIP_STATES.WAITING_PICKUP,TRIP_STATES.WAITING_HOP,TRIP_STATES.WAITING_RETURN].includes(state.tripState)&&!returnWaitTicker)returnWaitTicker=setInterval(render,1000);if(![TRIP_STATES.WAITING_PICKUP,TRIP_STATES.WAITING_HOP,TRIP_STATES.WAITING_RETURN].includes(state.tripState)&&returnWaitTicker){clearInterval(returnWaitTicker);returnWaitTicker=null}if(state.tripState===TRIP_STATES.REQUESTED&&!requestWaitTicker)requestWaitTicker=setInterval(()=>{const countdown=document.getElementById('request-countdown');if(countdown)countdown.textContent=formatRequestCountdown(store.getState().requestExpiresAt)},1000);if(state.tripState!==TRIP_STATES.REQUESTED&&requestWaitTicker){clearInterval(requestWaitTicker);requestWaitTicker=null}}); render();
if ('serviceWorker' in navigator) navigator.serviceWorker.getRegistrations().then(items => items.forEach(item => item.unregister()));
